func (node QualifiedName) FlowNode() *FlowNode {
	return node.Node.poolFlowNode(node.Node.uintField(8))
}

func (node QualifiedName) SetFlowNode(value *FlowNode) {
	index := node.Node.uintField(8)
	if index != 0 {
		node.Node.file.arena.poolFlowNode[index-1] = value
		return
	}
	if value == nil {
		return
	}
	node.Node.file.arena.poolFlowNode = append(node.Node.file.arena.poolFlowNode, value)
	node.Node.setUintField(8, arenaPoolIndex(len(node.Node.file.arena.poolFlowNode)))
}

func (node QualifiedName) facts() *atomic.Uint32 {
	return node.Node.atomicField(9)
}

func (node QualifiedName) Left() EntityName {
	return node.Node.nodeField(10)
}

func (node QualifiedName) SetLeft(value EntityName) {
	node.Node.setNodeField(10, value)
}

func (node QualifiedName) Right() MemberName {
	return node.Node.nodeField(11)
}

func (node QualifiedName) SetRight(value MemberName) {
	node.Node.setNodeField(11, value)
}

func (node QualifiedName) FlowNodeBase() FlowNodeBase { return FlowNodeBase{NodeDefault{node.Node}} }

func (node QualifiedName) CompositeBase() CompositeBase { return CompositeBase{NodeDefault{node.Node}} }

func (node QualifiedName) subtreeFactsWorker(self Node) SubtreeFacts {
	return (CompositeBase{NodeDefault{node.Node}}).subtreeFactsWorker(self)
}

func (f *NodeFactory) NewQualifiedName(left EntityName, right MemberName) Node {
	node := f.newNode(KindQualifiedName, arenaLayoutQualifiedName)
	data := QualifiedName{NodeDefault{node}}
	data.SetLeft(left)
	data.SetRight(right)
	f.onCreate(node)
	return node
}

func (f *NodeFactory) UpdateQualifiedName(node QualifiedName, left EntityName, right MemberName) Node {
	if left != node.Left() || right != node.Right() {
		return updateNode(f.NewQualifiedName(left, right), node.AsNode(), f.hooks)
	}
	return node.AsNode()
}

func (node QualifiedName) ForEachChild(v Visitor) bool {
	return node.forEachChild(v, node.Node.word(0))
}

func (node QualifiedName) forEachChild(v Visitor, record *uint32) bool {
	if *(*uint32)(unsafe.Add(unsafe.Pointer(record), 7*4)) != arenaLayoutQualifiedName {
		panic("AST node has incompatible arena layout")
	}
	data := (*[12]uint32)(unsafe.Pointer(record))
	return visit(v, node.Node.nodeFromOffset(data[10])) || visit(v, node.Node.nodeFromOffset(data[11]))
}

func (node QualifiedName) VisitEachChild(v *NodeVisitor) Node {
	return v.Factory.UpdateQualifiedName(node, v.visitNode(node.Left()), v.visitNode(node.Right()))
}

func (node QualifiedName) Clone(f NodeFactoryCoercible) Node {
	return cloneNode(f.AsNodeFactory().NewQualifiedName(node.Left(), node.Right()), node.AsNode(), f.AsNodeFactory().hooks)
}

func (node QualifiedName) computeSubtreeFacts() SubtreeFacts {
	return propagateSubtreeFacts(node.Left()) |
		propagateSubtreeFacts(node.Right())
}

func IsQualifiedName(node Node) bool {
	return node.Kind() == KindQualifiedName
}

