func IsLogicalOrCoalescingAssignmentOperator(kind Kind) bool {
	switch kind {
	case KindAmpersandAmpersandEqualsToken, KindBarBarEqualsToken, KindQuestionQuestionEqualsToken:
		return true
	}
	return false
}
